// ─── Colour helpers ────────────────────────────────────────────────────────
function lerp(a: number, b: number, t: number) { return Math.round(a + (b - a) * t); }

function greenShade(t: number): string {
  // light #DCF0E4 → brand #244D3B
  return `rgb(${lerp(220,36,t)},${lerp(240,77,t)},${lerp(228,59,t)})`;
}
function redShade(t: number): string {
  // light #FDECEA → dark red #7F1D1D
  return `rgb(${lerp(253,127,t)},${lerp(236,29,t)},${lerp(234,29,t)})`;
}
function goldShade(t: number): string {
  // light #FDF6E3 → brand gold #AF8E4A
  return `rgb(${lerp(253,175,t)},${lerp(246,142,t)},${lerp(227,74,t)})`;
}
function blueShade(t: number): string {
  // light #E8F4FD → dark blue #1E40AF
  return `rgb(${lerp(232,30,t)},${lerp(244,64,t)},${lerp(253,175,t)})`;
}

function scale(v: number, max: number): number {
  if (max === 0) return 0;
  return Math.pow(Math.min(v / max, 1), 0.5);
}

// ─── Metric definitions ────────────────────────────────────────────────────
type MetricId = 'orders' | 'revenue' | 'returned' | 'delivered' | 'avgOrder';

interface MetricDef {
  id:       MetricId;
  label:    string;
  icon:     string;
  shade:    (t: number) => string;
  format:   (v: number) => string;
  unit:     string;
}

// ─── Props ─────────────────────────────────────────────────────────────────
interface Props {
  orders:      Order[];
  font:        string;
  isMobile?:   boolean;
  isAdminAr?:  boolean;
  colors: { card:string; border:string; text:string; muted:string; green:string; gold:string; sub:string };
}

export default function WilayaOrdersMap({ orders, font, isMobile, isAdminAr = true, colors: C }: Props) {
  const [metric,  setMetric]  = useState<MetricId>('orders');
  const [hovered, setHovered] = useState<string | null>(null);
  const [pinned,  setPinned]  = useState<string | null>(null);

  const METRICS: MetricDef[] = [
    { id:'orders',   label: isAdminAr ? 'الطلبات'     : 'Commandes', icon:'M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4', shade: greenShade, format: v => v.toLocaleString(isAdminAr ? 'ar-DZ' : 'fr-DZ'),                                         unit: isAdminAr ? 'طلب'      : 'cmd'     },
    { id:'revenue',  label: isAdminAr ? 'الإيرادات'   : 'Revenus',   icon:'M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z', shade: goldShade, format: v => v.toLocaleString(isAdminAr ? 'ar-DZ' : 'fr-DZ') + (isAdminAr ? ' دج' : ' DA'), unit: isAdminAr ? 'دج'       : 'DA'      },
    { id:'returned', label: isAdminAr ? 'الروتور'     : 'Retours',   icon:'M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15', shade: redShade,   format: v => v.toLocaleString(isAdminAr ? 'ar-DZ' : 'fr-DZ'),                                         unit: isAdminAr ? 'طلب مرجع' : 'retours' },
    { id:'delivered',label: isAdminAr ? 'التسليم'     : 'Livraison', icon:'M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z',                                                                                    shade: greenShade, format: v => v.toLocaleString(isAdminAr ? 'ar-DZ' : 'fr-DZ'),                                         unit: isAdminAr ? 'مُسلَّم'  : 'livrés'  },
    { id:'avgOrder', label: isAdminAr ? 'متوسط الطلب' : 'Moy. cmd',  icon:'M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z', shade: blueShade,  format: v => v.toLocaleString(isAdminAr ? 'ar-DZ' : 'fr-DZ') + (isAdminAr ? ' دج' : ' DA'), unit: isAdminAr ? 'متوسط'    : 'moy.'    },
  ];

  // displayed = hovered (real-time) ?? pinned (last clicked) ?? top wilaya
  const displayed = hovered ?? pinned;

  const def = METRICS.find(m => m.id === metric)!;

  // Compute all metrics per DZ code
  const codeData = useMemo(() => {
    const counts:    Record<string, number> = {};
    const revenue:   Record<string, number> = {};
    const returned:  Record<string, number> = {};
    const delivered: Record<string, number> = {};
    const totalOrds: Record<string, number> = {};

    for (const o of orders) {
      const code = AR_TO_CODE[o.wilaya];
      if (!code) continue;
      counts[code]    = (counts[code]    ?? 0) + 1;
      totalOrds[code] = (totalOrds[code] ?? 0) + 1;
      if (o.status === 'delivered') {
        revenue[code]   = (revenue[code]   ?? 0) + o.total;
        delivered[code] = (delivered[code] ?? 0) + 1;
      }
      if (o.status === 'returned' || o.status === 'cancelled') {
        returned[code] = (returned[code] ?? 0) + 1;
      }
    }

    const avgOrder: Record<string, number> = {};
    for (const code of Object.keys(counts)) {
      avgOrder[code] = counts[code] > 0 ? Math.round((revenue[code] ?? 0) / counts[code]) : 0;
    }

    return { counts, revenue, returned, delivered, avgOrder };
  }, [orders]);

  const activeMap: Record<string, number> = codeData[
    metric === 'orders'    ? 'counts'    :
    metric === 'revenue'   ? 'revenue'   :
    metric === 'returned'  ? 'returned'  :
    metric === 'delivered' ? 'delivered' :
    'avgOrder'
  ] as Record<string, number>;

  const maxVal = Math.max(1, ...Object.values(activeMap));

  const top5 = Object.entries(activeMap)
    .filter(([, v]) => v > 0)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5);

  const hovVal      = hovered ? (activeMap[hovered] ?? 0) : 0;
  const codeToName  = (code: string) => isAdminAr ? (CODE_TO_AR[code] ?? code) : (CODE_TO_FR[code] ?? CODE_TO_AR[code] ?? code);
  const hovName     = hovered ? codeToName(hovered) : null;
  const dispCode    = displayed ?? top5[0]?.[0] ?? null;
  const dispName    = dispCode ? codeToName(dispCode) : null;
  const isDefault   = !displayed && top5[0]?.[0];
  const dispOrders  = dispCode ? (codeData.counts[dispCode]    ?? 0) : 0;
  const dispRev     = dispCode ? (codeData.revenue[dispCode]   ?? 0) : 0;
  const dispDel     = dispCode ? (codeData.delivered[dispCode] ?? 0) : 0;
  const dispRet     = dispCode ? (codeData.returned[dispCode]  ?? 0) : 0;

  return (
    <div style={{ display:'flex', flexDirection:'column', gap:12, fontFamily:font }}>

      {/* ── Metric tabs ─────────────────────────────────────────────────── */}
      <div style={{ display:'flex', gap:6, flexWrap:'wrap', direction: isAdminAr ? 'rtl' : 'ltr' }}>
        {METRICS.map(m => {
          const active = m.id === metric;
          return (
            <button
              key={m.id}
              onClick={() => setMetric(m.id)}
              style={{
                display:'flex', alignItems:'center', gap:5,
                padding:'5px 11px', borderRadius:20,
                border: active ? `1.5px solid ${C.green}` : `1px solid ${C.border}`,
                background: active ? C.green : C.card,
                color: active ? '#fff' : C.muted,
                fontSize:11, fontWeight: active ? 700 : 500,
                cursor:'pointer', fontFamily:font,
                transition:'all 0.18s',
              }}
            >
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink:0 }}>
                <path d={m.icon} />
              </svg>
              {m.label}
            </button>
          );
        })}
      </div>

      {/* ── Wilaya info card — always visible ──────────────────────────── */}
      <div style={{
        background: C.card,
        border: `1.5px solid ${hovered ? C.gold+'70' : C.border}`,
        borderRadius: 14, padding: '12px 16px', direction: isAdminAr ? 'rtl' : 'ltr',
        transition: 'border-color 0.25s',
        boxShadow: hovered ? `0 4px 18px rgba(175,142,74,.13)` : '0 2px 8px rgba(0,0,0,.05)',
      }}>
        {/* Header row */}
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:10 }}>
          <div style={{ display:'flex', alignItems:'center', gap:8 }}>
            {/* Location pin icon */}
            <div style={{
              width:28, height:28, borderRadius:8,
              background: hovered ? C.gold+'20' : C.sub+'30',
              display:'flex', alignItems:'center', justifyContent:'center',
              flexShrink:0, transition:'background 0.2s',
            }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={hovered ? C.gold : C.muted} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M15 10.5a3 3 0 11-6 0 3 3 0 016 0z"/>
                <path d="M19.5 10.5c0 7.142-7.5 11.25-7.5 11.25S4.5 17.642 4.5 10.5a7.5 7.5 0 1115 0z"/>
              </svg>
            </div>
            <div>
              <div style={{ fontSize:13, fontWeight:800, color: hovered ? C.text : C.muted, lineHeight:1, transition:'color 0.2s' }}>
                {dispName ?? (isAdminAr ? 'لا توجد بيانات' : 'Aucune donnée')}
              </div>
              {isDefault && !hovered && (
                <div style={{ fontSize:9, color:C.muted, marginTop:2, letterSpacing:'0.02em' }}>{isAdminAr ? 'الأعلى أداءً' : 'Meilleure perf.'}</div>
              )}
            </div>
          </div>
          <div style={{ fontSize:10, color:C.muted, fontFamily:'Inter', opacity:0.7 }}>
            {hovered ? (isAdminAr ? 'الولاية المختارة' : 'Wilaya sélect.') : (isAdminAr ? 'مرّر على الخريطة' : 'Survoler la carte')}
          </div>
        </div>

        {/* 4 metric tiles */}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr 1fr', gap:7 }}>
          {[
            { label: isAdminAr ? 'طلبات'    : 'Cmd',      val: dispOrders, fmt: (v:number) => String(v),                                              color: C.green },
            { label: isAdminAr ? 'إيرادات'  : 'Revenus',  val: dispRev,    fmt: (v:number) => (v/1000).toFixed(1)+(isAdminAr ? 'k دج' : 'k DA'),     color: C.gold  },
            { label: isAdminAr ? 'تسليم'    : 'Livraison',val: dispDel,    fmt: (v:number) => String(v),                                              color: '#10B981'},
            { label: isAdminAr ? 'مرجع'     : 'Retours',  val: dispRet,    fmt: (v:number) => String(v),                                              color: '#EF4444'},
          ].map(({ label, val, fmt, color }) => (
            <div key={label} style={{
              background: C.sub+'18', borderRadius:10, padding:'8px 6px',
              textAlign:'center', border:`1px solid ${C.border}`,
            }}>
              <div style={{ fontSize:14, fontWeight:800, color: (dispCode && val > 0) ? color : C.muted, lineHeight:1 }}>
                {dispCode ? fmt(val) : '—'}
              </div>
              <div style={{ fontSize:9, color:C.muted, marginTop:4, fontFamily:'Cairo, sans-serif' }}>{label}</div>
            </div>
          ))}
        </div>
      </div>

      {/* ── Map + sidebar ───────────────────────────────────────────────── */}
      <div style={{ display:'flex', flexDirection: isMobile ? 'column' : 'row', gap: isMobile ? 12 : 14, alignItems: isMobile ? 'stretch' : 'flex-start', direction: isAdminAr ? 'rtl' : 'ltr' }}>

        {/* SVG */}
        <div style={{ flex:1, minWidth:0, width: isMobile ? '100%' : 'auto' }}>
          <svg viewBox="0 0 1000 1000" style={{ width:'100%', height:'auto', display:'block', maxHeight: isMobile ? 340 : 'none' }}>
            {Object.entries(DZA_PATHS).map(([code, d]) => {
              const v    = activeMap[code] ?? 0;
              const t    = scale(v, maxVal);
              const fill = v === 0 ? '#EEF5EF' : def.shade(t);
              const isH  = hovered === code;
              return (
                <path
                  key={code}
                  d={d}
                  fill={fill}
                  stroke={isH || pinned === code ? C.gold : C.border}
                  strokeWidth={isH || pinned === code ? 2.5 : 0.7}
                  style={{ cursor:'pointer', transition:'fill 0.2s, stroke 0.15s' }}
                  onMouseEnter={() => setHovered(code)}
                  onMouseLeave={() => setHovered(null)}
                  onClick={() => setPinned(p => p === code ? null : code)}
                />
              );
            })}
          </svg>
        </div>

        {/* Sidebar: Top 5 + Legend */}
        <div style={{ width: isMobile ? '100%' : 165, flexShrink: isMobile ? 0 : 0, display:'flex', flexDirection: isMobile ? 'row' : 'column', gap:14, flexWrap:'nowrap', alignItems:'flex-start' }}>

          {/* Top 5 */}
          <div style={{ flex: isMobile ? 1 : 'none', minWidth: isMobile ? 140 : 'auto' }}>
            <div style={{ fontSize:11, fontWeight:700, color:C.muted, marginBottom:8, letterSpacing:'0.04em' }}>
              {isAdminAr ? 'أعلى 5 ولايات' : 'Top 5 wilayas'}
            </div>
            {top5.length === 0
              ? <div style={{ fontSize:12, color:C.muted }}>{isAdminAr ? 'لا توجد بيانات' : 'Aucune donnée'}</div>
              : top5.map(([code, val], idx) => {
                  const t    = scale(val, maxVal);
                  const fill = def.shade(t);
                  return (
                    <div
                      key={code}
                      style={{
                        display:'flex', alignItems:'center', gap:7, marginBottom:6,
                        padding:'4px 6px', borderRadius:6,
                        background: hovered === code ? C.sub+'33' : 'transparent',
                        transition:'background 0.15s', cursor:'default',
                      }}
                      onMouseEnter={() => setHovered(code)}
                      onMouseLeave={() => setHovered(null)}
                    >
                      <span style={{
                        width:18, height:18, borderRadius:4,
                        background:fill, border:`1px solid ${C.border}`,
                        flexShrink:0, display:'flex', alignItems:'center',
                        justifyContent:'center', fontSize:9,
                        color: t > 0.5 ? '#fff' : C.green, fontWeight:700,
                      }}>{idx+1}</span>
                      <span style={{ flex:1, fontSize:11, color:C.text, lineHeight:1.3 }}>
                        {codeToName(code)}
                      </span>
                      <span style={{ fontSize:10, fontWeight:700, color:C.green, flexShrink:0 }}>
                        {metric === 'revenue' || metric === 'avgOrder'
                          ? (val / 1000).toFixed(1) + 'k'
                          : val}
                      </span>
                    </div>
                  );
                })
            }
          </div>

          {/* Legend */}
          <div style={{ flex: isMobile ? 1 : 'none', minWidth: isMobile ? 100 : 'auto' }}>
            <div style={{ fontSize:11, fontWeight:700, color:C.muted, marginBottom:6, letterSpacing:'0.04em' }}>
              {isAdminAr ? 'المقياس' : 'Échelle'}
            </div>
            {[0, 0.25, 0.55, 0.80, 1].map((t, i) => {
              const labels = isAdminAr
                ? ['لا توجد','منخفض','متوسط','مرتفع','الأعلى']
                : ['Aucun','Faible','Moyen','Élevé','Max'];
              return (
                <div key={i} style={{ display:'flex', alignItems:'center', gap:6, marginBottom:4 }}>
                  <div style={{
                    width:13, height:13, borderRadius:3,
                    background: t === 0 ? '#EEF5EF' : def.shade(t),
                    border:`1px solid ${C.border}`, flexShrink:0,
                  }} />
                  <span style={{ fontSize:10, color:C.muted }}>{labels[i]}</span>
                </div>
              );
            })}
          </div>

        </div>
      </div>
    </div>
  );
}
